INSERT INTO `accessory` VALUES (1,'Plastron du chasseur','armor','rare','Un plastron solide taille pour les chasseurs aguerris des terres sauvages.','data:image/webp;base64,','2026-08-01 11:46:17',31,1),(2,'Tunique de voyageur','armor','standard','Une tunique legere et confortable ideale pour les longues routes.','data:image/webp;base64,','2026-08-01 11:46:17',32,1),(3,'Peau d\'Ombre','armor','legendary','Une armure legendaire qui absorbe la lumiere et dissimule son porteur.','data:image/webp;base64,','2026-08-01 11:46:17',33,1),(4,'Armure runique','armor','rare','Une armure gravee de runes protectrices anciennes et puissantes.','data:image/webp;base64,','2026-08-01 11:46:17',31,1),(5,'Baton de novice','weapon','standard','Un simple baton de bois parfait pour les apprentis mages debutants.','data:image/webp;base64,','2026-08-01 11:46:17',32,1),(6,'Azurine','weapon','rare','Un arc azure dont les fleches filent aussi vite que le vent du nord.','data:image/webp;base64,','2026-08-01 11:46:17',33,1),(7,'Lame du destin','weapon','legendary','Une lame legendaire qui n a jamais connu la moindre defaite au combat.','data:image/webp;base64,','2026-08-01 11:46:17',31,1),(8,'Epee courte','weapon','standard','Une epee courte maniable et fiable pour les combats rapproches.','data:image/webp;base64,','2026-08-01 11:46:17',32,1),(9,'Relique du Temps','relique','legendary','Une relique mysterieuse capable de ralentir le cours du temps lui meme.','data:image/webp;base64,','2026-08-01 11:46:17',33,1),(10,'Anneau de cuivre','relique','standard','Un modeste anneau de cuivre transmis de generation en generation.','data:image/webp;base64,','2026-08-01 11:46:17',31,1),(11,'Talisman des vents','relique','rare','Un talisman qui invoque les vents pour porter son porteur plus vite.','data:image/webp;base64,','2026-08-01 11:46:17',32,1),(12,'Amulette du Titan','relique','legendary','Une amulette renfermant la force colossale des anciens titans oublies.','data:image/webp;base64,','2026-08-01 11:46:17',33,1);
