INSERT INTO `comment` VALUES (12,'Un mage magnifiquement ecrit, j\'adore l\'ambiance mystique qui s\'en degage.',5,'valid','2026-06-24 12:00:00',29,24),(13,'Tres belle creation, la description est immersive et parfaitement coherente.',4,'valid','2026-06-26 19:30:00',30,24),(14,'Une archere redoutable, le design colle parfaitement a la classe choisie.',5,'valid','2026-07-03 08:15:00',28,26),(15,'Le cote druide est vraiment bien travaille, bravo pour l\'univers propose.',4,'valid','2026-07-12 21:05:00',30,27),(16,'Un paladin imposant, on sent la puissance rien qu\'en le regardant de loin.',5,'valid','2026-07-16 07:50:00',28,28),(17,'Enchanteresse pleine de charme, la palette de couleurs est vraiment superbe.',4,'valid','2026-07-25 15:40:00',29,29),(18,'Ce paladin en impose vraiment, l aura de justice ressort dans chaque detail. Du beau travail.',5,'valid','2026-07-28 14:20:00',29,28),(19,'J adore la douceur et la nature qui emanent de Sylthae, une druidesse tres inspiree. Bravo.',4,'valid','2026-07-30 09:10:00',28,27),(20,'Beau guerrier, j attends de voir la suite de son histoire avec impatience.',4,'pending','2026-08-11 10:00:00',30,25),(21,'Le design de Kaedor est vraiment reussi, on ressent toute sa force au premier coup d oeil.',5,'pending','2026-08-13 14:15:00',29,25),(22,'Bof, je trouve que ca manque un peu d originalite pour un enchanteur de ce niveau.',2,'refused','2026-08-09 18:30:00',28,29);
/*!40000 ALTER TABLE `comment` ENABLE KEYS */;
